require"active_support/logger_silence";require"active_support/logger_thread_safe_level";require"logger";module ActiveSupport;class Logger<::Logger;include LoggerSilence;def self.logger_outputs_to?(logger,*sources)loggers=if logger.is_a?(BroadcastLogger);logger.broadcasts;else [logger];end;logdevs=loggers.map{|logger|logger.instance_variable_get(:@logdev)};logger_sources=logdevs.filter_map{|logdev|logdev.try(:filename)||logdev.try(:dev)};normalize_sources(sources).intersect?(normalize_sources(logger_sources));end;def initialize(*args,**kwargs)super ;@formatter||=SimpleFormatter.new;end;class SimpleFormatter<::Logger::Formatter;def call(severity,timestamp,progname,msg)"#{String===msg ? msg: msg.inspect}\n";end;end;private;def self.normalize_sources(sources)sources.map do |source|source=source.path if source.respond_to?(:path);source=File.realpath(source) if source.is_a?(String)&&File.exist?(source);source;end;end;end;end
